#[derive(Debug, Clone)]
pub struct Neon {
    pub config: ClientConfig,
    pub project: ProjectNamespace,
    pub api_key: ApiKeyNamespace,
    pub operation: OperationNamespace,
    pub data_api: DataApiNamespace,
    pub auth_legacy: AuthLegacyNamespace,
    pub auth: AuthNamespace,
    pub branch: BranchNamespace,
    pub realtime: RealtimeNamespace,
    pub endpoint: EndpointNamespace,
    pub consumption: ConsumptionNamespace,
    pub organizations: OrganizationsNamespace,
    pub region: RegionNamespace,
    pub users: UsersNamespace,
    pub snapshot: SnapshotNamespace,
    pub buckets: BucketsNamespace,
    pub storage: StorageNamespace,
    pub ai_gateway: AiGatewayNamespace,
    pub logs: LogsNamespace,
    pub credentials: CredentialsNamespace,
    pub functions: FunctionsNamespace,
}

impl Neon {
    pub fn new(config: ClientConfig) -> Self {
        Self {
            project: ProjectNamespace::new(config.clone()),
            api_key: ApiKeyNamespace::new(config.clone()),
            operation: OperationNamespace::new(config.clone()),
            data_api: DataApiNamespace::new(config.clone()),
            auth_legacy: AuthLegacyNamespace::new(config.clone()),
            auth: AuthNamespace::new(config.clone()),
            branch: BranchNamespace::new(config.clone()),
            realtime: RealtimeNamespace::new(config.clone()),
            endpoint: EndpointNamespace::new(config.clone()),
            consumption: ConsumptionNamespace::new(config.clone()),
            organizations: OrganizationsNamespace::new(config.clone()),
            region: RegionNamespace::new(config.clone()),
            users: UsersNamespace::new(config.clone()),
            snapshot: SnapshotNamespace::new(config.clone()),
            buckets: BucketsNamespace::new(config.clone()),
            storage: StorageNamespace::new(config.clone()),
            ai_gateway: AiGatewayNamespace::new(config.clone()),
            logs: LogsNamespace::new(config.clone()),
            credentials: CredentialsNamespace::new(config.clone()),
            functions: FunctionsNamespace::new(config.clone()),
            config,
        }
    }

    /// Turns SDK logging on and configures it. Logging is OFF by default — this
    /// SDK reports nothing until you call this (or construct the client with a
    /// `ClientConfig` whose logging is enabled). Reports go to the endpoint this
    /// build was generated with, or to the `endpoint` you pass; with neither,
    /// nothing is sent.
    ///
    /// This ALWAYS enables logging — `enabled` on the passed config is ignored,
    /// since `LoggingConfig::default()` keeps logging disabled at rest and
    /// honouring it would make the obvious "configure and turn on" call a
    /// silent no-op. PII filtering remains on unless the supplied config
    /// explicitly sets `filter_pii` to false.
    pub fn set_logging_config(&mut self, logging: Option<LoggingConfig>) -> LoggingConfig {
        if let Some(next) = logging {
            self.config.logging = next;
        }
        self.config.logging.enabled = true;
        self.project = ProjectNamespace::new(self.config.clone());
        self.api_key = ApiKeyNamespace::new(self.config.clone());
        self.operation = OperationNamespace::new(self.config.clone());
        self.data_api = DataApiNamespace::new(self.config.clone());
        self.auth_legacy = AuthLegacyNamespace::new(self.config.clone());
        self.auth = AuthNamespace::new(self.config.clone());
        self.branch = BranchNamespace::new(self.config.clone());
        self.realtime = RealtimeNamespace::new(self.config.clone());
        self.endpoint = EndpointNamespace::new(self.config.clone());
        self.consumption = ConsumptionNamespace::new(self.config.clone());
        self.organizations = OrganizationsNamespace::new(self.config.clone());
        self.region = RegionNamespace::new(self.config.clone());
        self.users = UsersNamespace::new(self.config.clone());
        self.snapshot = SnapshotNamespace::new(self.config.clone());
        self.buckets = BucketsNamespace::new(self.config.clone());
        self.storage = StorageNamespace::new(self.config.clone());
        self.ai_gateway = AiGatewayNamespace::new(self.config.clone());
        self.logs = LogsNamespace::new(self.config.clone());
        self.credentials = CredentialsNamespace::new(self.config.clone());
        self.functions = FunctionsNamespace::new(self.config.clone());
        self.config.logging.clone()
    }
}
